//! Turns `assets/icons` into a table of `include_bytes!`, one entry per SVG.
//!
//! The table is keyed by the path gpui asks for — `icons/close.svg`, forward slashes on every
//! platform — and sorted, so the lookup can binary-search it and the generated file is the same
//! from one build to the next.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

pub fn generate() {
    let root = Path::new("assets");
    let icons = root.join("icons");
    // A directory here makes Cargo rescan everything under it, so a file added, removed or
    // edited rebuilds the table.
    println!("cargo:rerun-if-changed={}", icons.display());

    let mut files = Vec::new();
    collect_svgs(&icons, &mut files);
    // `include_bytes!` resolves a relative path against the generated file in OUT_DIR, so the
    // table names each file from the crate root instead.
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let mut entries: Vec<(String, PathBuf)> = files
        .into_iter()
        .map(|path| {
            let key = path
                .strip_prefix(root)
                .expect("collected under assets")
                .components()
                .map(|part| part.as_os_str().to_str().expect("asset paths are UTF-8"))
                .collect::<Vec<_>>()
                .join("/");
            (key, manifest.join(&path))
        })
        .collect();
    entries.sort();

    let mut out = String::new();
    writeln!(out, "// Generated by build/assets.rs. Do not edit.").unwrap();
    writeln!(out, "static FILES: &[(&str, &[u8])] = &[").unwrap();
    for (key, absolute) in &entries {
        let absolute = absolute.to_str().expect("asset paths are UTF-8");
        writeln!(out, "    ({key:?}, include_bytes!({absolute:?})),").unwrap();
    }
    writeln!(out, "];").unwrap();

    let target = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR")).join("assets.rs");
    std::fs::write(&target, out).unwrap_or_else(|error| panic!("write assets.rs: {error}"));
}

fn collect_svgs(directory: &Path, files: &mut Vec<PathBuf>) {
    let entries = std::fs::read_dir(directory)
        .unwrap_or_else(|error| panic!("read {}: {error}", directory.display()));
    for entry in entries {
        let path = entry
            .unwrap_or_else(|error| panic!("read {}: {error}", directory.display()))
            .path();
        if path.is_dir() {
            collect_svgs(&path, files);
        } else if path.extension().is_some_and(|extension| extension == "svg") {
            files.push(path);
        }
    }
}
